MA2:MA(CLOSE,M2);
MA3:MA(CLOSE,M3);
MA4:MA(CLOSE,M4);
MA5:MA(CLOSE,M5);
MA6:MA(CLOSE,M6);
MA7:MA(CLOSE,M7);
MA8:MA(CLOSE,M8);
MA9:MA(CLOSE,M9);
MA10:MA(CLOSE,M10);

DIF:=ADVANCE-DECLINE;
EMA1:=EMA(DIF,N1);
EMA2:=EMA(DIF,N2);
MCL:EMA1-EMA2;
MAMCL1:EMA1;
MAMCL2:EMA2;

DIF:=CLOSE-REF(CLOSE,1);
VU:=IF(DIF>=0,DIF,0);
VD:=IF(DIF<0,-DIF,0);
MAU1:=MEMA(VU,M1);
MAD1:=MEMA(VD,M1);
MAU2:=MEMA(VU,M2);
MAD2:=MEMA(VD,M2);
RSI1:MA(100*MAU1/(MAU1+MAD1),M1);
RSI2:MA(100*MAU2/(MAU2+MAD2),M2);

MTR:=SUM(MAX(MAX(HIGH-LOW,ABS(HIGH-REF(CLOSE,1))),ABS(REF(CLOSE,1)-LOW)),N);
HD :=HIGH-REF(HIGH,1);
LD :=REF(LOW,1)-LOW;
DMP:=SUM(IF(HD>0&&HD>LD,HD,0),N);
DMM:=SUM(IF(LD>0&&LD>HD,LD,0),N);
PDI: DMP*100/MTR;
MDI: DMM*100/MTR;
ADX: MA(ABS(MDI-PDI)/(MDI+PDI)*100,M);
ADXR:(ADX+REF(ADX,M))/2;

TH:=MAX(HIGH,REF(CLOSE,1));
TL:=MIN(LOW,REF(CLOSE,1));
ACC1:=SUM(CLOSE-TL,N1)/SUM(TH-TL,N1);
ACC2:=SUM(CLOSE-TL,N2)/SUM(TH-TL,N2);
ACC3:=SUM(CLOSE-TL,N3)/SUM(TH-TL,N3);
UOS:(ACC1*N2*N3+ACC2*N1*N3+ACC3*N1*N2)*100/(N1*N2+N1*N3+N2*N3);
MAUOS:EXPMEMA(UOS,M);

TOTAL:=IF(PERIOD=1,5,IF(PERIOD=2,15,IF(PERIOD=3,30,IF(PERIOD=4,60,IF(PERIOD=5,TOTALFZNUM,1)))));
DTIME:=IF(FROMOPEN<15,0.1746/15*FROMOPEN,
IF(FROMOPEN<30,0.1746+0.1059/15*(FROMOPEN-15),
IF(FROMOPEN<45,0.2805+0.0823/15*(FROMOPEN-30),
IF(FROMOPEN<60,0.3628+0.0635/15*(FROMOPEN-45),
IF(FROMOPEN<75,0.4263+0.0559/15*(FROMOPEN-60),
IF(FROMOPEN<90,0.4822+0.0477/15*(FROMOPEN-75),
IF(FROMOPEN<105,0.5299+0.0432/15*(FROMOPEN-90),
IF(FROMOPEN<120,0.5731+0.0392/15*(FROMOPEN-105),
IF(FROMOPEN<135,0.6123+0.0446/15*(FROMOPEN-120),
IF(FROMOPEN<150,0.6569+0.0430/15*(FROMOPEN-135),
IF(FROMOPEN<165,0.6999+0.0440/15*(FROMOPEN-150),
IF(FROMOPEN<180,0.7439+0.0414/15*(FROMOPEN-165),
IF(FROMOPEN<195,0.7853+0.0436/15*(FROMOPEN-180),
IF(FROMOPEN<210,0.8289+0.0439/15*(FROMOPEN-195),
IF(FROMOPEN<225,0.8728+0.0531/15*(FROMOPEN-210),
0.9260+0.0740/15*(FROMOPEN-225)
)))))))))))))));
MTIME:=MOD(FROMOPEN,TOTAL);
CTIME:=IF(MTIME<0.5,TOTAL,IF((PERIOD=5 AND SETCODE<3),DTIME*240,MTIME));
VVOL:=IF((CURRBARSCOUNT=1 AND DYNAINFO(8)>1),VOL*(TOTAL+3)/(CTIME+3),DRAWNULL);
STICKLINE((CURRBARSCOUNT=1 AND DYNAINFO(8)>1),VVOL,0,-1,-1),COLOR00C0C0;
VOLUME:VOL,VOLSTICK;
MAVOL1:MA(VOLUME,M1);
MAVOL2:MA(VOLUME,M2);

TOTAL:=IF(PERIOD=1,5,IF(PERIOD=2,15,IF(PERIOD=3,30,IF(PERIOD=4,60,IF(PERIOD=5,TOTALFZNUM,1)))));
DTIME:=IF(FROMOPEN<15,0.1746/15*FROMOPEN,
IF(FROMOPEN<30,0.1746+0.1059/15*(FROMOPEN-15),
IF(FROMOPEN<45,0.2805+0.0823/15*(FROMOPEN-30),
IF(FROMOPEN<60,0.3628+0.0635/15*(FROMOPEN-45),
IF(FROMOPEN<75,0.4263+0.0559/15*(FROMOPEN-60),
IF(FROMOPEN<90,0.4822+0.0477/15*(FROMOPEN-75),
IF(FROMOPEN<105,0.5299+0.0432/15*(FROMOPEN-90),
IF(FROMOPEN<120,0.5731+0.0392/15*(FROMOPEN-105),
IF(FROMOPEN<135,0.6123+0.0446/15*(FROMOPEN-120),
IF(FROMOPEN<150,0.6569+0.0430/15*(FROMOPEN-135),
IF(FROMOPEN<165,0.6999+0.0440/15*(FROMOPEN-150),
IF(FROMOPEN<180,0.7439+0.0414/15*(FROMOPEN-165),
IF(FROMOPEN<195,0.7853+0.0436/15*(FROMOPEN-180),
IF(FROMOPEN<210,0.8289+0.0439/15*(FROMOPEN-195),
IF(FROMOPEN<225,0.8728+0.0531/15*(FROMOPEN-210),
0.9260+0.0740/15*(FROMOPEN-225)
)))))))))))))));
MTIME:=MOD(FROMOPEN,TOTAL);
CTIME:=IF(MTIME<0.5,TOTAL,IF((PERIOD=5 AND SETCODE<3),DTIME*240,MTIME));
VAMO:=IF((CURRBARSCOUNT=1 AND DYNAINFO(8)>1),AMOUNT/10000.0*(TOTAL+3)/(CTIME+3),DRAWNULL);
STICKLINE((CURRBARSCOUNT=1 AND DYNAINFO(8)>1),VAMO,0,-1,-1),COLOR00C0C0;
AMOW:AMOUNT/10000.0,VOLSTICK;
AMO1:MA(AMOW,M1);
AMO2:MA(AMOW,M2);

持仓量:VOLINSTK;
成交:VOL,COLORLIRED;
仓差:VOLINSTK-REF(VOLINSTK,1),NODRAW;
STICKLINE(仓差>0 AND C>REF(C,1),0,仓差,2,3),COLORRED;
STICKLINE(仓差>0 AND C<REF(C,1),0,仓差,2,3),COLORCYAN;
STICKLINE(仓差>0 AND C=REF(C,1),0,仓差,2,3),COLORGRAY;
STICKLINE(仓差<0 AND C>REF(C,1),0,仓差,2,3),COLORRED;
STICKLINE(仓差<0 AND C<REF(C,1),0,仓差,2,3),COLORCYAN;
STICKLINE(仓差<0 AND C=REF(C,1),0,仓差,2,3),COLORGRAY;

CCYD:=CCL-REF(CCL,1);
SPYD:=C-REF(C,1);
多头增仓:IF(SPYD>=0 AND CCYD>=0,ABS(CCYD),DRAWNULL),COLOR3232FF,NODRAW;
空头减仓:IF(SPYD>0 AND CCYD<0,ABS(CCYD),DRAWNULL),COLOR3232FF,NODRAW;
空头增仓:IF(SPYD<0 AND CCYD>=0,ABS(CCYD),DRAWNULL),COLORFFFF54,NODRAW;
多头减仓:IF(SPYD<0 AND CCYD<0,ABS(CCYD),DRAWNULL),COLORFFFF54,NODRAW;
STICKLINE(SPYD>=0 AND CCYD>=0,0,CCYD,3,1),COLOR3232FF;
STICKLINE(SPYD>0 AND CCYD<0,CCYD,0,3,1),COLOR3232FF;
STICKLINE(SPYD<0 AND CCYD>=0,CCYD,0,3,0),COLORFFFF54;
STICKLINE(SPYD<0 AND CCYD<0,CCYD,0,3,0),COLORFFFF54;

VV:=(HIGH+OPEN+LOW+CLOSE)/4;
VMA1:MA(VV,M1);
VMA2:MA(VV,M2);
VMA3:MA(VV,M3);
VMA4:MA(VV,M4);
VMA5:MA(VV,M5);

MID:=MA(C,M);
VART1:=POW((C-MID),2);
VART2:=MA(VART1,20);
VART3:=SQRT(VART2);
UPPER:=MID+2*VART3;
LOWER:=MID-2*VART3;
BOLL:IF(BARSCOUNT(C)=0,C,IF(BARSCOUNT(C)>0 AND BARSCOUNT(C)<=19,REF(C,1),REF(MID,1))),COLOR30C7ED;
上轨线:REF(UPPER,1),COLORFF00FF;
下轨线:REF(LOWER,1),COLORB9D559;
MA5:MA(C,5),COLORRED;
HSXTJ:=BOLL>REF(BOLL,1) AND CROSS(C,BOLL);
STICKLINE(HSXTJ,CLOSE,OPEN,3,0),COLOR30C7ED;
STICKLINE(HSXTJ,L,H,0.1,0),COLOR30C7ED;
ZSXTJ:=(BOLL>REF(BOLL,1) AND CROSS(MA5,BOLL)) OR (MA5>BOLL AND CROSS(C,MA5));
STICKLINE(ZSXTJ,CLOSE,OPEN,3,0),COLORRED;
STICKLINE(ZSXTJ,L,H,0.1,0),COLORRED;
REDSXTJ:=CROSS(C,上轨线);
STICKLINE(REDSXTJ,CLOSE,OPEN,3,0),COLORFF00FF;
STICKLINE(REDSXTJ,L,H,0.1,0),COLORFF00FF;

【箱顶】:PEAK(CLOSE,N,1)*0.98;
【箱底】:TROUGH(CLOSE,N,1)*1.02;
【箱高】:100*(【箱顶】-【箱底】)/【箱底】,NODRAW;

MA1:IF(PERIOD==0,DRAWNULL,MA(CLOSE,M1));
MA2:IF(PERIOD==0,DRAWNULL,MA(CLOSE,M2));
MA3:IF(PERIOD==0,DRAWNULL,MA(CLOSE,M3));
MA4:IF(PERIOD==0,DRAWNULL,MA(CLOSE,M4));
N:=CURRBARSCOUNT;
B:=C<REF(C,4);
T1:= BARSLASTCOUNT(B);
A_B1:=(T1>9) AND MOD(T1,9)=1;
A_B9:=(T1>9) AND MOD(T1,9)=0;
B1:=(N=6 AND REFXV(COUNT(B,6),5)=6) OR (N=7 AND REFXV(COUNT(B,7),6)=7) OR (N=8 AND REFXV(COUNT(B,8),7)=8) OR (N>=9 AND REFXV(COUNT(B,9),8)=9);
DRAWNUMBER_DIF(B1 AND (REF(B,1)=0 OR A_B1),1,1,8),COLORMAGENTA;
B9:=(N>=1 AND COUNT(B,9)=9);
DRAWNUMBER_DIF(B9 AND (REF(B,9)=0 OR A_B9),1,9,1),COLORRED;
S:=C>REF(C,4);
T2:= BARSLASTCOUNT(S);
A_S1:=(T2>9) AND MOD(T2,9)=1;
A_S9:=(T2>9) AND MOD(T2,9)=0;
S1:=(N=6 AND REFXV(COUNT(S,6),5)=6) OR (N=7 AND REFXV(COUNT(S,7),6)=7) OR (N=8 AND REFXV(COUNT(S,8),7)=8) OR (N>=9 AND REFXV(COUNT(S,9),8)=9);
DRAWNUMBER_DIF(S1 AND (REF(S,1)=0 OR A_S1),1,1,8),COLORMAGENTA,DRAWABOVE;
S9:=(N>=1 AND COUNT(S,9)=9);
DRAWNUMBER_DIF(S9 AND (REF(S,9)=0 OR A_S9),1,9,1),COLORGREEN,DRAWABOVE;

JCX:=(H+L+O+2*C)/5;
MJ20:=EMA(JCX,39);
MJ30:=EMA(JCX,99);
牛熊线:PARTLINE(MJ30,IF(MJ20>=MJ30,RGB(255,0,0),IF(MJ20<MJ30,RGB(0,255,0),DRAWNULL)),0),LINETHICK2;
决策线:MJ20,COLORYELLOW,LINETHICK1,DOTLINE;

AA:=ABS((2*CLOSE+HIGH+LOW)/4-MA(CLOSE,N))/MA(CLOSE,N);
济安线:DMA((2*CLOSE+LOW+HIGH)/4,AA),LINETHICK3,COLORMAGENTA;
CC:=(CLOSE/济安线);
MA1:=MA(CC*(2*CLOSE+HIGH+LOW)/4,3);
MAAA:=((MA1-济安线)/济安线)/3;
TMP:=MA1-MAAA*MA1;
J:IF(TMP<=济安线,济安线,DRAWNULL),LINETHICK3,COLORCYAN;
A:TMP,LINETHICK2,COLORBROWN;
X:IF(TMP<=济安线,TMP,DRAWNULL),LINETHICK2,COLORGREEN;

HLC:=REF(MA((HIGH+LOW+CLOSE)/3,N),1);
HV:=EMA(HHV(HIGH,N),3);
LV:=EMA(LLV(LOW,N),3);
STOR:EMA(2*HV-LV,3);
MIDR:EMA(HLC+HV-LV,3);
WEKR:EMA(HLC*2-LV,3);
WEKS:EMA(HLC*2-HV,3);
MIDS:EMA(HLC-HV+LV,3);
STOS:EMA(2*LV-HV,3);

总量能:("999999$AMO"+"399001$AMO")/100000000,NODRAW;
STICKLINE(总量能>0,0,总量能,2,0),COLORLIGRAY;
沪主板:("SH999999$AMO"-"SH000688$AMO")/100000000,LINETHICK2,COLORRED;
深主板:("SZ399001$AMO"-"SZ399006$AMO")/100000000,LINETHICK2,COLORMAGENTA;
创业科创:("SZ399006$AMO")/100000000+("SH000688$AMO")/100000000,LINETHICK2,COLORYELLOW;

UPTJ1:=CLOSE>REF(CLOSE,1);
UPTJ2:=(CLOSE==REF(CLOSE,1) && REF(CLOSE,1)>REF(CLOSE,2));
UPTJ3:=MAX(OPEN,CLOSE)<REF(C,BARSLAST(CLOSE>REF(CLOSE,1))) AND MIN(OPEN,CLOSE)>REF(O,BARSLAST(CLOSE>REF(CLOSE,1)));
UPTJ4:=NOT (H<REF(H,1) AND L<REF(L,1));
UP:=(UPTJ1 || UPTJ2 || UPTJ3) AND UPTJ4;
DOWN:=NOT(UP);
M1:=BARSLASTCOUNT(UP);
N1:=BARSLASTCOUNT(DOWN);
CZB:=IF(M1=1 OR N1=1,2*INTPART(VOL*100/10000),INTPART(VOL*100/10000));
SZ:=IF(M1>0,SUM(CZB,M1),-1*SUM(CZB,N1));
GY:=IF(N1>0,SUM(CZB,N1),0);
XQ:=IF(M1>0,SUM(CZB,M1),0);
NOTEXT1:STICKLINE(M1>0,0,XQ,1,0),COLORRED;
NOTEXT2:STICKLINE(N1>0,0,GY,1,0),COLORGREEN;
WSB:SZ,NODRAW;

NN:=(H+L)/2;
上唇:REF(MA(NN,5),3),COLOR40FF40;
牙齿:REF(MA(NN,8),5),COLOR0000C0;
下颚:REF(MA(NN,13),8),COLORFF4040;

MA3:EMA(CLOSE,3),COLORC08080;
MA5:EMA(CLOSE,5),COLORC08080;
MA8:EMA(CLOSE,8),COLORC08080;
MA10:EMA(CLOSE,10),COLORC08080;
MA12:EMA(CLOSE,12),COLORC08080;
MA15:EMA(CLOSE,15),COLORC08080;
MA30:EMA(CLOSE,30),COLOR0080FF;
MA35:EMA(CLOSE,35),COLOR0080FF;
MA40:EMA(CLOSE,40),COLOR0080FF;
MA45:EMA(CLOSE,45),COLOR0080FF;
MA50:EMA(CLOSE,50),COLOR0080FF;
MA60:EMA(CLOSE,60),COLOR0080FF;

VAR2:=CLOSE*VOL;
VAR3:=EMA((EMA(VAR2,3)/EMA(VOL,3)+EMA(VAR2,6)/EMA(VOL,6)+EMA(VAR2,12)/EMA(VOL,12)+EMA(VAR2,24)/EMA(VOL,24))/4,N);
SUP:1.06*VAR3;
SDN:VAR3*0.94;
VAR4:=EMA(CLOSE,9);
LUP:EMA(VAR4*1.14,5);
LDN:EMA(VAR4*0.86,5);

AA:=MA((2*CLOSE+HIGH+LOW)/4,5); 
通道1:AA*N/100; 
通道2:AA*(200-N)/100; 
CC:=ABS((2*CLOSE+HIGH+LOW)/4-MA(CLOSE,20))/MA(CLOSE,20); 
DD:=DMA(CLOSE,CC); 
通道3:(1+M/100)*DD; 
通道4:(1-M/100)*DD;

周期高点:REF(HHV(H,X1),1);
周期低点:REF(LLV(L,X2),1);
平空开多:=HIGH>=周期高点;
平多开空:=LOW<=周期低点;
BUYSHORT_BUY(平空开多,LOW);
SELL_SELLSHORT(平多开空,HIGH);
AUTOFILTER;

NN:=MIN(BARSCOUNT(C),N); 
个股: (CLOSE-REF(CLOSE,NN))/REF(CLOSE,NN)*100; 
大盘: (INDEXC-REF(INDEXC,NN))/REF(INDEXC,NN)*100; 
强弱值:EMA(个股-大盘,2),COLORSTICK;

AA:=ABS((2*CLOSE+HIGH+LOW)/4-MA(CLOSE,N))/MA(CLOSE,N); 
轨道:DMA(CLOSE,AA);
压力线:(1+M/100)*轨道; 
支撑线:(1-M/100)*轨道;

VAR1:=(CLOSE-LLV(LOW,60))/(HHV(HIGH,60)-LLV(LOW,60))*80; 
B:SMA(VAR1,N,1); 
VAR2:SMA(B,M,1); 
绝路航标:IF(CROSS(B,VAR2) AND B<40,50,0);

{该模型为示范模型,仅用于说明算法语法,用户需根据自己交易经验修改后再实际应用}
{变量赋值}
MA1:=MA(CLOSE,SHORT);
MA2:=MA(CLOSE,LONG);
{交易条件}
平空开多:=CROSS(MA1,MA2);
平多开空:=CROSS(MA2,MA1);
{交易系统}
BUYSHORT_BUY(平空开多,LOW);
SELL_SELLSHORT(平多开空,HIGH);
{交易信号过滤}
AUTOFILTER;

{该模型为示范模型,仅用于说明算法语法,用户需根据自己交易经验修改后再实际应用}
DIFF:=EMA(CLOSE,SHORT)-EMA(CLOSE,LONG);
DEA:=EMA(DIFF,MID);
MACD:=2*(DIFF-DEA);
平空开多:=CROSS(MACD,0);
平多开空:=CROSS(0,MACD);
BUYSHORT_BUY(平空开多,LOW);
SELL_SELLSHORT(平多开空,HIGH);
AUTOFILTER;

{该模型为示范模型,仅用于说明算法语法,用户需根据自己交易经验修改后再实际应用}
RSV:=(CLOSE-LLV(LOW,N))/(HHV(HIGH,N)-LLV(LOW,N))*100;
K:=SMA(RSV,M1,1);
D:=SMA(K,M1,1);
J:=3*K-2*D;
平空开多:=CROSS(J,0);
平多开空:=CROSS(100,J);
BUYSHORT_BUY(平空开多,LOW);
SELL_SELLSHORT(平多开空,HIGH);
AUTOFILTER;

{该模型为示范模型,仅用于说明算法语法,用户需根据自己交易经验修改后再实际应用}
MA1:=REF(MA((HIGH+LOW+CLOSE)/3,AVGLENGTH),1);
UPPERBAND:=MA1+REF(MA(TR,ATRLENGTH),1);
LOWERBAND:=MA1-REF(MA(TR,ATRLENGTH),1);
开多条件:=MA1>REF(MA1,1) AND HIGH>=UPPERBAND;
平多条件:=LOW<=MA1;
开空条件:=MA1<REF(MA1,1) AND LOW<=LOWERBAND;
平空条件:=HIGH>=MA1;
GL1:=NOT(开多条件=1 AND 平多条件=1);
GL2:=NOT(开空条件=1 AND 平空条件=1);
SELL(平多条件,HIGH);
BUYSHORT(平空条件,LOW);
BUY(开多条件 AND GL1,LOW);
SELLSHORT(开空条件 AND GL2,HIGH);
AUTOFILTER;

{该模型为示范模型,仅用于说明算法语法,用户需根据自己交易经验修改后再实际应用}
{变量赋值}
NBAR:=BARSLAST(DATE<>REF(DATE,1))+1;
HHN:REF(HHV(H,N),1);
LLN:REF(LLV(L,N),1);
MID:(HHN+LLN)/2;
T1:=TIME>900 AND TIME <1455;{根据品种的交易时间和选择的周期做相应调整}
T2:=TIME>=1455;{根据品种的交易时间和选择的周期做相应调整}
{交易条件}
开多条件:=H>HHN AND (HHN-MID)/MID<M/1000 AND NBAR>=30 AND T1;
开空条件:=L<LLN AND (MID-LLN)/MID<M/1000 AND NBAR>=30 AND T1;
{交易系统}
BUY(开多条件,LOW);
SELLSHORT(开空条件,HIGH);
SELL(T2,HIGH);
BUYSHORT(T2,LOW);
AUTOFILTER;

{该模型为示范模型,仅用于说明算法语法,用户需根据自己交易经验修改后再实际应用}
{变量赋值}
N:=BARSLAST(DATE<>REF(DATE,1))+1;
HHH:=VALUEWHEN(TIME<=900+NMIN1,HHV(H,N));
LLL:=VALUEWHEN(TIME<=900+NMIN1,LLV(L,N));
上轨:HHH+M*MINDIFF;
下轨:LLL-M*MINDIFF;
{交易条件}
开多条件:=C>上轨;
开空条件:=C<下轨;
交易时间:=TIME>900+NMIN1 AND TIME<1450;
平仓时间:=TIME>=1500-NMIN2;
{交易系统}
BUY(开多条件 AND 交易时间,LOW);
SELLSHORT(开空条件 AND 交易时间,HIGH);
SELL(平仓时间,HIGH);
BUYSHORT(平仓时间,LOW);
AUTOFILTER;

hh:=if(c/ref(c,1)>1.093 and l>ref(h,1),2*c-ref(c,1)-h,2*c-h-l);
v1:=BARSCOUNT(c);
v2:=2*ref(c,v1)-ref(h,v1)-ref(l,v1);
DK:sum(hh,0)+v2;
MDK1:MA(DK,P1);
MDK2:MA(DK,P2);

ZY1:=CLOSE/INDEXC*1000;
A1:=IF(ZY1>HHV(ZY1,3),10,0);
A2:=IF(ZY1>HHV(ZY1,5),15,0);
A3:=IF(ZY1>HHV(ZY1,10),20,0);
A4:=IF(ZY1>HHV(ZY1,2),10,0);
A5:=COUNT(ZY1>REF(ZY1,1),9)*5;
强势股评分:A1+A2+A3+A4+A5;

VAR1:=CLOSE-LOW;
VAR2:=HIGH-LOW;
VAR3:=CLOSE-HIGH;
VAR4:=IF(HIGH>LOW,(VAR1/VAR2+VAR3/VAR2)*VOL,0);
CYW: SUM(VAR4,10)/10000, COLORSTICK;

SM:=(OPEN+HIGH+CLOSE+LOW)/4;
SMID:=MA(SM,D);
IM:=(INDEXO+INDEXH+INDEXL+INDEXC)/4;
IMID:=MA(IM,D);
SI1:=(SMID-REF(SMID,1))/SMID;
II:=(IMID-REF(IMID,1))/IMID;
RADER1:SUM((SI1-II)*2,S)*1000;
RADERMA:SMA(RADER1,M,1);

LC := REF(CLOSE,1);
VID := SUM(VOL,2)/(((HHV(HIGH,2)-LLV(LOW,2)))*100);
RC := (CLOSE-LC)*VID;
LONG := SUM(RC,0);
DIFF := SMA(LONG,10,1);
DEA := SMA(LONG,20,1);
LON : DIFF-DEA;
LONMA : MA(LON,N);
LONT : LON, COLORSTICK;

VAR1:=MA((VOL-REF(VOL,1))/REF(VOL,1),5);
VAR2:=(CLOSE-MA(CLOSE,24))/MA(CLOSE,24)*100;
MY: VAR2*(1+VAR1);
SHT: MY, COLORSTICK;
